@Test
public void testTimestampMicros() throws Exception {
    Schema schema = getSchema("logical/test_timestamp_micros.avsc");
    List<Long> data = Arrays.asList(10000L, 20000L, 30000L, 40000L, 50000L);
    List<LocalDateTime> expected = Arrays.asList(DateUtility.getLocalDateTimeFromEpochMicro(10000), DateUtility.getLocalDateTimeFromEpochMicro(20000), DateUtility.getLocalDateTimeFromEpochMicro(30000), DateUtility.getLocalDateTimeFromEpochMicro(40000), DateUtility.getLocalDateTimeFromEpochMicro(50000));
    VectorSchemaRoot root = writeAndRead(schema, data);
    FieldVector vector = root.getFieldVectors().get(0);
    checkPrimitiveResult(expected, vector);
}

