@Test
public void testIncludeMetadata() {
    JdbcToArrowConfigBuilder builder = new JdbcToArrowConfigBuilder(allocator, calendar, false);
    JdbcToArrowConfig config = builder.build();
    assertFalse(config.shouldIncludeMetadata());
    builder.setIncludeMetadata(true);
    config = builder.build();
    assertTrue(config.shouldIncludeMetadata());
    config = new JdbcToArrowConfigBuilder(allocator, calendar, true).build();
    assertTrue(config.shouldIncludeMetadata());
    config = new JdbcToArrowConfig(allocator, calendar, /* include metadata */
    true, /* reuse vector schema root */
    true, null, null, JdbcToArrowConfig.NO_LIMIT_BATCH_SIZE, null);
    assertTrue(config.shouldIncludeMetadata());
    assertTrue(config.isReuseVectorSchemaRoot());
    config = new JdbcToArrowConfig(allocator, calendar, /* include metadata */
    false, /* reuse vector schema root */
    false, null, null, JdbcToArrowConfig.NO_LIMIT_BATCH_SIZE, null);
    assertFalse(config.shouldIncludeMetadata());
    assertFalse(config.isReuseVectorSchemaRoot());
}

@Test
public void testArraySubTypes() {
    JdbcToArrowConfigBuilder builder = new JdbcToArrowConfigBuilder(allocator, calendar, false);
    JdbcToArrowConfig config = builder.build();
    final int columnIndex = 1;
    final String columnName = "COLUMN";
    assertNull(config.getArraySubTypeByColumnIndex(columnIndex));
    assertNull(config.getArraySubTypeByColumnName(columnName));
    final HashMap<Integer, JdbcFieldInfo> indexMapping = new HashMap<Integer, JdbcFieldInfo>();
    indexMapping.put(2, new JdbcFieldInfo(Types.BIGINT));
    final HashMap<String, JdbcFieldInfo> fieldMapping = new HashMap<String, JdbcFieldInfo>();
    fieldMapping.put("NEW_COLUMN", new JdbcFieldInfo(Types.BINARY));
    builder.setArraySubTypeByColumnIndexMap(indexMapping);
    builder.setArraySubTypeByColumnNameMap(fieldMapping);
    config = builder.build();
    assertNull(config.getArraySubTypeByColumnIndex(columnIndex));
    assertNull(config.getArraySubTypeByColumnName(columnName));
    indexMapping.put(columnIndex, new JdbcFieldInfo(Types.BIT));
    fieldMapping.put(columnName, new JdbcFieldInfo(Types.BLOB));
    assertNotNull(config.getArraySubTypeByColumnIndex(columnIndex));
    assertEquals(Types.BIT, config.getArraySubTypeByColumnIndex(columnIndex).getJdbcType());
    assertEquals(Types.BLOB, config.getArraySubTypeByColumnName(columnName).getJdbcType());
}

@Test
public void testZeroRowResultSet() throws Exception {
    for (boolean reuseVectorSchemaRoot : new boolean[] { false, true }) {
        try (BufferAllocator allocator = new RootAllocator(Integer.MAX_VALUE)) {
            ResultSet rs = ResultSetUtility.generateEmptyResultSet();
            JdbcToArrowConfig config = new JdbcToArrowConfigBuilder(allocator, JdbcToArrowUtils.getUtcCalendar(), /* include metadata */
            false).setReuseVectorSchemaRoot(reuseVectorSchemaRoot).build();
            ArrowVectorIterator iter = JdbcToArrow.sqlToArrowVectorIterator(rs, config);
            assertTrue("Iterator on zero row ResultSet should haveNext() before use", iter.hasNext());
            VectorSchemaRoot root = iter.next();
            assertNotNull("VectorSchemaRoot from first next() result should never be null", root);
            assertEquals("VectorSchemaRoot from empty ResultSet should have zero rows", 0, root.getRowCount());
            assertFalse("hasNext() should return false on empty ResultSets after initial next() call", iter.hasNext());
        }
    }
}

@Test
public void testBasicResultSet() throws Exception {
    try (ResultSetUtility.MockResultSet resultSet = ResultSetUtility.generateBasicResultSet(3)) {
        // Before row 1:
        assertTrue(resultSet.isBeforeFirst());
        assertFalse(resultSet.isFirst());
        assertFalse(resultSet.isLast());
        assertFalse(resultSet.isAfterLast());
        assertThrows(SQLException.class, () -> resultSet.getString(1));
        // Row 1:
        assertTrue(resultSet.next());
        assertFalse(resultSet.isBeforeFirst());
        assertTrue(resultSet.isFirst());
        assertFalse(resultSet.isLast());
        assertFalse(resultSet.isAfterLast());
        assertEquals("row number: 1", resultSet.getString(1));
        // Row 2:
        assertTrue(resultSet.next());
        assertFalse(resultSet.isBeforeFirst());
        assertFalse(resultSet.isFirst());
        assertFalse(resultSet.isLast());
        assertFalse(resultSet.isAfterLast());
        assertEquals("row number: 2", resultSet.getString(1));
        // Row 3:
        assertTrue(resultSet.next());
        assertFalse(resultSet.isBeforeFirst());
        assertFalse(resultSet.isFirst());
        assertTrue(resultSet.isLast());
        assertFalse(resultSet.isAfterLast());
        assertEquals("row number: 3", resultSet.getString(1));
        // After row 3:
        assertFalse(resultSet.next());
