@Test
public void testIncorrectNullability() throws Exception {
    // ARROW-17005: ResultSetMetaData may indicate a field is non-nullable even when there are nulls
    ResultSetUtility.MockResultSetMetaData.MockColumnMetaData columnMetaData = ResultSetUtility.MockResultSetMetaData.MockColumnMetaData.builder().index(1).sqlType(Types.INTEGER).nullable(ResultSetMetaData.columnNoNulls).build();
    ResultSetMetaData metadata = new ResultSetUtility.MockResultSetMetaData(Collections.singletonList(columnMetaData));
    final ResultSetUtility.MockResultSet.Builder resultSetBuilder = ResultSetUtility.MockResultSet.builder().setMetaData(metadata).addDataElement(new ResultSetUtility.MockDataElement(1024, Types.INTEGER)).finishRow().addDataElement(new ResultSetUtility.MockDataElement(null, Types.INTEGER)).finishRow();
    final Schema notNullSchema = new Schema(Collections.singletonList(Field.notNullable(/*name=*/
    null, new ArrowType.Int(32, true))));
    final Schema nullSchema = new Schema(Collections.singletonList(Field.nullable(/*name=*/
    null, new ArrowType.Int(32, true))));
    try (final ResultSet rs = resultSetBuilder.build()) {
        JdbcToArrowConfig config = new JdbcToArrowConfigBuilder(allocator, JdbcToArrowUtils.getUtcCalendar(), /* include metadata */
        false).setReuseVectorSchemaRoot(reuseVectorSchemaRoot).build();
        try (ArrowVectorIterator iter = JdbcToArrow.sqlToArrowVectorIterator(rs, config)) {
            assertTrue(iter.hasNext());
            final VectorSchemaRoot root = iter.next();
            // The wrong data is returned here
            assertEquals(notNullSchema, root.getSchema());
            assertEquals(2, root.getRowCount());
            final IntVector ints = (IntVector) root.getVector(0);
            assertEquals(1024, ints.get(0));
            assertFalse(ints.isNull(1));
            assertFalse(iter.hasNext());
            root.close();
        }
        rs.beforeFirst();
        // Override the nullability to get the correct result
        final Map<Integer, JdbcFieldInfo> typeMapping = new HashMap<>();
        JdbcFieldInfo realFieldInfo = new JdbcFieldInfo(Types.INTEGER, ResultSetMetaData.columnNullable, /*precision*/
        0, /*scale*/
        0);
        typeMapping.put(1, realFieldInfo);
        config = new JdbcToArrowConfigBuilder(allocator, JdbcToArrowUtils.getUtcCalendar(), /* include metadata */
        false).setReuseVectorSchemaRoot(reuseVectorSchemaRoot).setExplicitTypesByColumnIndex(typeMapping).build();
        try (ArrowVectorIterator iter = JdbcToArrow.sqlToArrowVectorIterator(rs, config)) {
            assertTrue(iter.hasNext());
            final VectorSchemaRoot root = iter.next();
            assertEquals(nullSchema, root.getSchema());
            assertEquals(2, root.getRowCount());
            final IntVector ints = (IntVector) root.getVector(0);
            assertEquals(1024, ints.get(0));
            assertTrue(ints.isNull(1));
            assertFalse(iter.hasNext());
            root.close();
        }
        rs.beforeFirst();
        // columnNullableUnknown won't override the metadata
        realFieldInfo = new JdbcFieldInfo(Types.INTEGER, ResultSetMetaData.columnNullableUnknown, /*precision*/
        0, /*scale*/
        0);
        typeMapping.put(1, realFieldInfo);
        config = new JdbcToArrowConfigBuilder(allocator, JdbcToArrowUtils.getUtcCalendar(), /* include metadata */
        false).setReuseVectorSchemaRoot(reuseVectorSchemaRoot).setExplicitTypesByColumnIndex(typeMapping).build();
        try (ArrowVectorIterator iter = JdbcToArrow.sqlToArrowVectorIterator(rs, config)) {
            assertTrue(iter.hasNext());
            final VectorSchemaRoot root = iter.next();
            assertEquals(notNullSchema, root.getSchema());
            assertEquals(2, root.getRowCount());
            final IntVector ints = (IntVector) root.getVector(0);
            assertEquals(1024, ints.get(0));
            assertFalse(ints.isNull(1));
            assertFalse(iter.hasNext());
            root.close();
        }
    }
}

@Test
public void testOrcJniReader() throws Exception {
    TypeDescription schema = TypeDescription.fromString("struct<x:int,y:string>");
    File testFile = new File(testFolder.getRoot(), "test-orc");
    Writer writer = OrcFile.createWriter(new Path(testFile.getAbsolutePath()), OrcFile.writerOptions(new Configuration()).setSchema(schema));
    VectorizedRowBatch batch = schema.createRowBatch();
    LongColumnVector longColumnVector = (LongColumnVector) batch.cols[0];
    BytesColumnVector bytesColumnVector = (BytesColumnVector) batch.cols[1];
    for (int r = 0; r < 1024; ++r) {
        int row = batch.size++;
        longColumnVector.vector[row] = r;
        byte[] buffer = ("Last-" + (r * 3)).getBytes(StandardCharsets.UTF_8);
        bytesColumnVector.setRef(row, buffer, 0, buffer.length);
    }
    writer.addRowBatch(batch);
    writer.close();
    OrcReader reader = new OrcReader(testFile.getAbsolutePath(), allocator);
    assertEquals(1, reader.getNumberOfStripes());
    ArrowReader stripeReader = reader.nextStripeReader(1024);
    VectorSchemaRoot schemaRoot = stripeReader.getVectorSchemaRoot();
    stripeReader.loadNextBatch();
    List<FieldVector> fields = schemaRoot.getFieldVectors();
    assertEquals(2, fields.size());
    IntVector intVector = (IntVector) fields.get(0);
    VarCharVector varCharVector = (VarCharVector) fields.get(1);
    for (int i = 0; i < 1024; ++i) {
        assertEquals(i, intVector.get(i));
        assertEquals("Last-" + (i * 3), new String(varCharVector.get(i), StandardCharsets.UTF_8));
    }
    assertFalse(stripeReader.loadNextBatch());
    assertNull(reader.nextStripeReader(1024));
    stripeReader.close();
    reader.close();
}

