        for (int i = 0; i < VECTOR_LENGTH; i++) {
            if (i % 10 == 0) {
                assertEquals(0, encodedVector.get(i));
            } else {
                assertArrayEquals(rawVector.get(i), String.valueOf(encodedVector.get(i)).getBytes());
            }
        }
        // perform decoding
