        comparator.attachVectors(listVector1, listVector2);
        // prefix is smaller
        assertTrue(comparator.compare(0, 0) < 0);
    }
    try (ListVector listVector1 = createListVector(11);
        ListVector listVector2 = createListVector(11)) {
