        assertTrue(comparator.compare(7, 7) == 0);
        assertTrue(comparator.compare(6, 0) > 0);
        assertTrue(comparator.compare(6, 8) > 0);
        assertTrue(comparator.compare(6, 3) > 0);
    }
}

