@Test
public void testArrowFileZstdRoundTrip() throws Exception {
    // Prepare sample data
    final BufferAllocator allocator = new RootAllocator(Integer.MAX_VALUE);
    List<Field> fields = new ArrayList<>();
    fields.add(new Field("col", FieldType.notNullable(new ArrowType.Utf8()), new ArrayList<>()));
    VectorSchemaRoot root = VectorSchemaRoot.create(new Schema(fields), allocator);
    final int rowCount = 10;
    GenerateSampleData.generateTestData(root.getVector(0), rowCount);
    root.setRowCount(rowCount);
    // Write an in-memory compressed arrow file
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    try (final ArrowFileWriter writer = new ArrowFileWriter(root, null, Channels.newChannel(out), new HashMap<>(), IpcOption.DEFAULT, CommonsCompressionFactory.INSTANCE, CompressionUtil.CodecType.ZSTD, Optional.of(7))) {
        writer.start();
        writer.writeBatch();
        writer.end();
    }
    // Read the in-memory compressed arrow file with CommonsCompressionFactory provided
    try (ArrowFileReader reader = new ArrowFileReader(new ByteArrayReadableSeekableByteChannel(out.toByteArray()), allocator, CommonsCompressionFactory.INSTANCE)) {
        Assert.assertEquals(1, reader.getRecordBlocks().size());
        Assert.assertTrue(reader.loadNextBatch());
        Assert.assertTrue(root.equals(reader.getVectorSchemaRoot()));
        Assert.assertFalse(reader.loadNextBatch());
    }
    // Read the in-memory compressed arrow file without CompressionFactory provided
    try (ArrowFileReader reader = new ArrowFileReader(new ByteArrayReadableSeekableByteChannel(out.toByteArray()), allocator, NoCompressionCodec.Factory.INSTANCE)) {
        Assert.assertEquals(1, reader.getRecordBlocks().size());
        Exception exception = Assert.assertThrows(IllegalArgumentException.class, () -> reader.loadNextBatch());
        String expectedMessage = "Please add arrow-compression module to use CommonsCompressionFactory for ZSTD";
        Assert.assertEquals(expectedMessage, exception.getMessage());
    }
}

@ParameterizedTest
@MethodSource("codecs")
void testCompressFixedWidthBuffers(int vectorLength, CompressionCodec codec) throws Exception {
    // prepare vector to compress
    IntVector origVec = new IntVector("vec", allocator);
    origVec.allocateNew(vectorLength);
    for (int i = 0; i < vectorLength; i++) {
        if (i % 10 == 0) {
            origVec.setNull(i);
        } else {
            origVec.set(i, i);
        }
    }
    origVec.setValueCount(vectorLength);
    int nullCount = origVec.getNullCount();
    // compress & decompress
    List<ArrowBuf> origBuffers = origVec.getFieldBuffers();
    List<ArrowBuf> compressedBuffers = compressBuffers(codec, origBuffers);
    List<ArrowBuf> decompressedBuffers = deCompressBuffers(codec, compressedBuffers);
    assertEquals(2, decompressedBuffers.size());
    // orchestrate new vector
    IntVector newVec = new IntVector("new vec", allocator);
    newVec.loadFieldBuffers(new ArrowFieldNode(vectorLength, nullCount), decompressedBuffers);
    // verify new vector
    assertEquals(vectorLength, newVec.getValueCount());
    for (int i = 0; i < vectorLength; i++) {
        if (i % 10 == 0) {
            assertTrue(newVec.isNull(i));
        } else {
            assertEquals(i, newVec.get(i));
        }
    }
    newVec.close();
    AutoCloseables.close(decompressedBuffers);
}

