@Test
public void testDirectReservationListener() throws Exception {
    ParquetWriteSupport writeSupport = ParquetWriteSupport.writeTempFile(AVRO_SCHEMA_USER, TMP.newFolder(), 1, "a");
    NativeMemoryPool pool = NativeMemoryPool.createListenable(DirectReservationListener.instance());
    FileSystemDatasetFactory factory = new FileSystemDatasetFactory(rootAllocator(), pool, FileFormat.PARQUET, writeSupport.getOutputURI());
    ScanOptions options = new ScanOptions(100);
    long initReservation = DirectReservationListener.instance().getCurrentDirectMemReservation();
    List<ArrowRecordBatch> datum = collectResultFromFactory(factory, options);
    long reservation = DirectReservationListener.instance().getCurrentDirectMemReservation();
    AutoCloseables.close(datum);
    AutoCloseables.close(pool);
    long finalReservation = DirectReservationListener.instance().getCurrentDirectMemReservation();
    Assert.assertTrue(reservation >= initReservation);
    Assert.assertEquals(initReservation, finalReservation);
}

@Test
public void testCustomReservationListener() throws Exception {
    ParquetWriteSupport writeSupport = ParquetWriteSupport.writeTempFile(AVRO_SCHEMA_USER, TMP.newFolder(), 1, "a");
    final AtomicLong reserved = new AtomicLong(0L);
    ReservationListener listener = new ReservationListener() {

        @Override
        public void reserve(long size) {
            reserved.getAndAdd(size);
        }

        @Override
        public void unreserve(long size) {
            reserved.getAndAdd(-size);
        }
    };
    NativeMemoryPool pool = NativeMemoryPool.createListenable(listener);
    FileSystemDatasetFactory factory = new FileSystemDatasetFactory(rootAllocator(), pool, FileFormat.PARQUET, writeSupport.getOutputURI());
    ScanOptions options = new ScanOptions(100);
    long initReservation = reserved.get();
    List<ArrowRecordBatch> datum = collectResultFromFactory(factory, options);
    long reservation = reserved.get();
    AutoCloseables.close(datum);
    AutoCloseables.close(pool);
    long finalReservation = reserved.get();
    Assert.assertTrue(reservation >= initReservation);
    Assert.assertEquals(initReservation, finalReservation);
}

@Test
public void testErrorThrownFromReservationListener() throws Exception {
    final String errorMessage = "ERROR_MESSAGE";
    ParquetWriteSupport writeSupport = ParquetWriteSupport.writeTempFile(AVRO_SCHEMA_USER, TMP.newFolder(), 1, "a");
    final AtomicLong reserved = new AtomicLong(0L);
    ReservationListener listener = new ReservationListener() {

        @Override
        public void reserve(long size) {
            throw new IllegalArgumentException(errorMessage);
        }

        @Override
        public void unreserve(long size) {
            // no-op
        }
    };
    NativeMemoryPool pool = NativeMemoryPool.createListenable(listener);
    FileSystemDatasetFactory factory = new FileSystemDatasetFactory(rootAllocator(), pool, FileFormat.PARQUET, writeSupport.getOutputURI());
    ScanOptions options = new ScanOptions(100);
    long initReservation = reserved.get();
    Assertions.assertThrows(IllegalArgumentException.class, () -> {
        collectResultFromFactory(factory, options);
    }, errorMessage);
    long reservation = reserved.get();
    AutoCloseables.close(pool);
    long finalReservation = reserved.get();
    Assert.assertEquals(initReservation, reservation);
    Assert.assertEquals(initReservation, finalReservation);
}

@Test
public void testRunQueryLocalFiles() throws Exception {
    //Query:
    //SELECT id, name FROM Users
    //Isthmus:
    //./isthmus-macOS-0.7.0  -c "CREATE TABLE USERS ( id INT NOT NULL, name VARCHAR(150));" "SELECT id, name FROM Users"
    //VARCHAR(150) -> is mapping to -> {ARROW:extension:name=varchar, ARROW:extension:metadata=varchar{length:150}}
    Map<String, String> metadataName = new HashMap<>();
    metadataName.put("ARROW:extension:name", "varchar");
    metadataName.put("ARROW:extension:metadata", "varchar{length:150}");
    final Schema schema = new Schema(Arrays.asList(Field.nullable("ID", new ArrowType.Int(32, true)), new Field("NAME", new FieldType(true, new ArrowType.Utf8(), null, metadataName), null)), Collections.emptyMap());
    ParquetWriteSupport writeSupport = ParquetWriteSupport.writeTempFile(AVRO_SCHEMA_USER, TMP.newFolder(), 1, "a", 11, "b", 21, "c");
    try (ArrowReader arrowReader = new AceroSubstraitConsumer(rootAllocator()).runQuery(new String(Files.readAllBytes(Paths.get(TestAceroSubstraitConsumer.class.getClassLoader().getResource("substrait/local_files_users.json").toURI()))).replace("FILENAME_PLACEHOLDER", writeSupport.getOutputURI()))) {
        assertEquals(schema, arrowReader.getVectorSchemaRoot().getSchema());
        int rowcount = 0;
        while (arrowReader.loadNextBatch()) {
            rowcount += arrowReader.getVectorSchemaRoot().getRowCount();
        }
        assertEquals(3, rowcount);
    }
}

