@Test
public void checkReflectionMetadata() {
    // This metadata is needed for gRPC reflection to work.
    final ExecutorService executorService = Executors.newSingleThreadExecutor();
    try (final BufferAllocator allocator = new RootAllocator(Integer.MAX_VALUE)) {
        final FlightBindingService service = new FlightBindingService(allocator, new NoOpFlightProducer(), ServerAuthHandler.NO_OP, executorService);
        final ServerServiceDefinition definition = service.bindService();
        assertEquals(FlightServiceGrpc.getServiceDescriptor().getSchemaDescriptor(), definition.getServiceDescriptor().getSchemaDescriptor());
        final Map<String, MethodDescriptor<?, ?>> definedMethods = new HashMap<>();
        final Map<String, MethodDescriptor<?, ?>> serviceMethods = new HashMap<>();
        // Make sure that the reflection metadata object is identical across all the places where it's accessible
        definition.getMethods().forEach(method -> definedMethods.put(method.getMethodDescriptor().getFullMethodName(), method.getMethodDescriptor()));
        definition.getServiceDescriptor().getMethods().forEach(method -> serviceMethods.put(method.getFullMethodName(), method));
        for (final MethodDescriptor<?, ?> descriptor : FlightServiceGrpc.getServiceDescriptor().getMethods()) {
            final String methodName = descriptor.getFullMethodName();
            Assertions.assertTrue(definedMethods.containsKey(methodName), "Method is missing from ServerServiceDefinition: " + methodName);
            Assertions.assertTrue(definedMethods.containsKey(methodName), "Method is missing from ServiceDescriptor: " + methodName);
            assertEquals(descriptor.getSchemaDescriptor(), definedMethods.get(methodName).getSchemaDescriptor());
            assertEquals(descriptor.getSchemaDescriptor(), serviceMethods.get(methodName).getSchemaDescriptor());
        }
    } finally {
        executorService.shutdown();
    }
}

