@Test
public void testExecuteShouldRunSelectQuery() throws SQLException {
    collector.checkThat(statement.execute(SAMPLE_QUERY_CMD), // Means this is a SELECT query.
    is(true));
    final Set<Byte> numbers = IntStream.range(0, SAMPLE_QUERY_ROWS).boxed().map(Integer::byteValue).collect(Collectors.toCollection(HashSet::new));
    try (final ResultSet resultSet = statement.getResultSet()) {
        final int columnCount = resultSet.getMetaData().getColumnCount();
        collector.checkThat(columnCount, is(1));
        int rowCount = 0;
        for (; resultSet.next(); rowCount++) {
            collector.checkThat(numbers.remove(resultSet.getByte(1)), is(true));
        }
        collector.checkThat(rowCount, is(equalTo(SAMPLE_QUERY_ROWS)));
    }
    collector.checkThat(numbers, is(Collections.emptySet()));
    collector.checkThat((long) statement.getUpdateCount(), is(allOf(equalTo(statement.getLargeUpdateCount()), equalTo(-1L))));
}

