    }
}

@Test
public void testShouldInterruptFlightStreamsIfQueryIsCancelledMidQuerying() throws SQLException, InterruptedException {
    try (final Statement statement = connection.createStatement()) {
        final CountDownLatch latch = new CountDownLatch(1);
        final Set<Exception> exceptions = synchronizedSet(new HashSet<>(1));
        final Thread thread = new Thread(() -> {
            try (final ResultSet resultSet = statement.executeQuery(CoreMockedSqlProducers.LEGACY_REGULAR_SQL_CMD)) {
                final int cachedColumnCount = resultSet.getMetaData().getColumnCount();
                Thread.sleep(300);
                while (resultSet.next()) {
                    resultSet.getObject(RANDOM.nextInt(cachedColumnCount) + 1);
                }
            } catch (final SQLException | InterruptedException e) {
                exceptions.add(e);
            } finally {
                latch.countDown();
            }
        });
        thread.setName("Test Case: interrupt query execution before first retrieval");
        thread.start();
        statement.cancel();
        thread.join();
        collector.checkThat(exceptions.stream().map(Exception::getMessage).map(StringBuilder::new).reduce(StringBuilder::append).orElseThrow(IllegalArgumentException::new).toString(), is("Statement canceled"));
    }
}

@Test
public void testShouldInterruptFlightStreamsIfQueryIsCancelledMidProcessingForTimeConsumingQueries() throws SQLException, InterruptedException {
    final String query = CoreMockedSqlProducers.LEGACY_CANCELLATION_SQL_CMD;
    try (final Statement statement = connection.createStatement()) {
        final Set<Exception> exceptions = synchronizedSet(new HashSet<>(1));
        final Thread thread = new Thread(() -> {
            try (final ResultSet ignored = statement.executeQuery(query)) {
                fail();
            } catch (final SQLException e) {
                exceptions.add(e);
            }
        });
        thread.setName("Test Case: interrupt query execution mid-process");
        thread.setPriority(Thread.MAX_PRIORITY);
        thread.start();
        // Let the other thread attempt to retrieve results.
        Thread.sleep(5000);
        statement.cancel();
        thread.join();
        collector.checkThat(exceptions.stream().map(Exception::getMessage).map(StringBuilder::new).reduce(StringBuilder::append).orElseThrow(IllegalStateException::new).toString(), anyOf(is(format("Error while executing SQL \"%s\": Query canceled", query)), allOf(containsString(format("Error while executing SQL \"%s\"", query)), containsString("CANCELLED"))));
    }
}

@Test
public void testShouldInterruptFlightStreamsIfQueryTimeoutIsOver() throws SQLException {
    final String query = CoreMockedSqlProducers.LEGACY_CANCELLATION_SQL_CMD;
    final int timeoutValue = 2;
    final String timeoutUnit = "SECONDS";
    try (final Statement statement = connection.createStatement()) {
        statement.setQueryTimeout(timeoutValue);
        final Set<Exception> exceptions = new HashSet<>(1);
        try {
            statement.executeQuery(query);
        } catch (final Exception e) {
            exceptions.add(e);
        }
        final Throwable comparisonCause = exceptions.stream().findFirst().orElseThrow(RuntimeException::new).getCause().getCause();
        collector.checkThat(comparisonCause, is(instanceOf(SQLTimeoutException.class)));
        collector.checkThat(comparisonCause.getMessage(), is(format("Query timed out after %d %s", timeoutValue, timeoutUnit)));
    }
}

