@Test
public void testTransformerBuilderWorksCorrectly() throws Exception {
    final VarBinaryVector field1 = rootAllocatorTestRule.createVarBinaryVector("FIELD_1");
    final VarBinaryVector field2 = rootAllocatorTestRule.createVarBinaryVector("FIELD_2");
    final VarBinaryVector field3 = rootAllocatorTestRule.createVarBinaryVector("FIELD_3");
    try (final VectorSchemaRoot originalRoot = VectorSchemaRoot.of(field1, field2, field3);
        final VectorSchemaRoot clonedRoot = cloneVectorSchemaRoot(originalRoot)) {
        final VectorSchemaRootTransformer.Builder builder = new VectorSchemaRootTransformer.Builder(originalRoot.getSchema(), rootAllocator);
        builder.renameFieldVector("FIELD_3", "FIELD_3_RENAMED");
        builder.addEmptyField("EMPTY_FIELD", new ArrowType.Bool());
        builder.renameFieldVector("FIELD_2", "FIELD_2_RENAMED");
        builder.renameFieldVector("FIELD_1", "FIELD_1_RENAMED");
        final VectorSchemaRootTransformer transformer = builder.build();
        final Schema transformedSchema = new Schema(ImmutableList.of(Field.nullable("FIELD_3_RENAMED", new ArrowType.Binary()), Field.nullable("EMPTY_FIELD", new ArrowType.Bool()), Field.nullable("FIELD_2_RENAMED", new ArrowType.Binary()), Field.nullable("FIELD_1_RENAMED", new ArrowType.Binary())));
        try (final VectorSchemaRoot transformedRoot = createVectorSchemaRoot(transformedSchema)) {
            Assert.assertSame(transformedRoot, transformer.transform(clonedRoot, transformedRoot));
            Assert.assertEquals(transformedSchema, transformedRoot.getSchema());
            final int rowCount = originalRoot.getRowCount();
            Assert.assertEquals(rowCount, transformedRoot.getRowCount());
            final VarBinaryVector originalField1 = (VarBinaryVector) originalRoot.getVector("FIELD_1");
            final VarBinaryVector originalField2 = (VarBinaryVector) originalRoot.getVector("FIELD_2");
            final VarBinaryVector originalField3 = (VarBinaryVector) originalRoot.getVector("FIELD_3");
            final VarBinaryVector transformedField1 = (VarBinaryVector) transformedRoot.getVector("FIELD_1_RENAMED");
            final VarBinaryVector transformedField2 = (VarBinaryVector) transformedRoot.getVector("FIELD_2_RENAMED");
            final VarBinaryVector transformedField3 = (VarBinaryVector) transformedRoot.getVector("FIELD_3_RENAMED");
            final FieldVector emptyField = transformedRoot.getVector("EMPTY_FIELD");
            for (int i = 0; i < rowCount; i++) {
                Assert.assertArrayEquals(originalField1.getObject(i), transformedField1.getObject(i));
                Assert.assertArrayEquals(originalField2.getObject(i), transformedField2.getObject(i));
                Assert.assertArrayEquals(originalField3.getObject(i), transformedField3.getObject(i));
                Assert.assertNull(emptyField.getObject(i));
            }
        }
    }
}

@Test
public void testOutputTypesForAdd() {
    ArrowType.Decimal operand1 = getDecimal(30, 10);
    ArrowType.Decimal operand2 = getDecimal(30, 10);
    ArrowType.Decimal resultType = DecimalTypeUtil.getResultTypeForOperation(DecimalTypeUtil.OperationType.ADD, operand1, operand2);
    Assert.assertTrue(getDecimal(31, 10).equals(resultType));
    operand1 = getDecimal(30, 6);
    operand2 = getDecimal(30, 5);
    resultType = DecimalTypeUtil.getResultTypeForOperation(DecimalTypeUtil.OperationType.ADD, operand1, operand2);
    Assert.assertTrue(getDecimal(32, 6).equals(resultType));
    operand1 = getDecimal(30, 10);
    operand2 = getDecimal(38, 10);
    resultType = DecimalTypeUtil.getResultTypeForOperation(DecimalTypeUtil.OperationType.ADD, operand1, operand2);
    Assert.assertTrue(getDecimal(38, 9).equals(resultType));
    operand1 = getDecimal(38, 10);
    operand2 = getDecimal(38, 38);
    resultType = DecimalTypeUtil.getResultTypeForOperation(DecimalTypeUtil.OperationType.ADD, operand1, operand2);
    Assert.assertTrue(getDecimal(38, 9).equals(resultType));
    operand1 = getDecimal(38, 10);
    operand2 = getDecimal(38, 2);
    resultType = DecimalTypeUtil.getResultTypeForOperation(DecimalTypeUtil.OperationType.ADD, operand1, operand2);
    Assert.assertTrue(getDecimal(38, 6).equals(resultType));
}

