@Test
public void testIf() throws Exception {
    /*
     * when x < 10 then 0
     * when x < 20 then 1
     * when x < 30 then 2
     * when x < 40 then 3
     * when x < 50 then 4
     * when x < 60 then 5
     * when x < 70 then 6
     * when x < 80 then 7
     * when x < 90 then 8
     * when x < 100 then 9
     * when x < 110 then 10
     * when x < 120 then 11
     * when x < 130 then 12
     * when x < 140 then 13
     * when x < 150 then 14
     * when x < 160 then 15
     * when x < 170 then 16
     * when x < 180 then 17
     * when x < 190 then 18
     * when x < 200 then 19
     * else 20
     */
    Field x = Field.nullable("x", int32);
    TreeNode xNode = TreeBuilder.makeField(x);
    // if (x < 100) then 9 else 10
    int returnValue = 20;
    TreeNode topNode = TreeBuilder.makeLiteral(returnValue);
    int compareWith = 200;
    while (compareWith >= 10) {
        // cond (x < compareWith)
        TreeNode condNode = TreeBuilder.makeFunction("less_than", Lists.newArrayList(xNode, TreeBuilder.makeLiteral(compareWith)), boolType);
        topNode = TreeBuilder.makeIf(// cond (x < compareWith)
        condNode, // then returnValue
        TreeBuilder.makeLiteral(returnValue), // else topNode
        topNode, int32);
        compareWith -= 10;
        returnValue--;
    }
    ExpressionTree expr = TreeBuilder.makeExpression(topNode, x);
    Schema schema = new Schema(Lists.newArrayList(x));
    long timeTaken = timedProject(new BoundedInt32DataAndVectorGenerator(allocator, 250), schema, Lists.newArrayList(expr), 1 * MILLION, 16 * THOUSAND, 4);
    System.out.println("Time taken for projecting 10m records of nestedIf is " + timeTaken + "ms");
    Assert.assertTrue(timeTaken <= 15 * toleranceRatio);
}

