@Test
public void testCompare() throws GandivaException {
    Decimal aType = new Decimal(38, 3, 128);
    Decimal bType = new Decimal(38, 2, 128);
    Field a = Field.nullable("a", aType);
    Field b = Field.nullable("b", bType);
    List<Field> args = Lists.newArrayList(a, b);
    List<ExpressionTree> exprs = new ArrayList<>(Arrays.asList(TreeBuilder.makeExpression("equal", args, Field.nullable("eq", boolType)), TreeBuilder.makeExpression("not_equal", args, Field.nullable("ne", boolType)), TreeBuilder.makeExpression("less_than", args, Field.nullable("lt", boolType)), TreeBuilder.makeExpression("less_than_or_equal_to", args, Field.nullable("le", boolType)), TreeBuilder.makeExpression("greater_than", args, Field.nullable("gt", boolType)), TreeBuilder.makeExpression("greater_than_or_equal_to", args, Field.nullable("ge", boolType))));
    Schema schema = new Schema(args);
    Projector eval = Projector.make(schema, exprs);
    List<ValueVector> output = null;
    ArrowRecordBatch batch = null;
    try {
        int numRows = 4;
        String[] aValues = new String[] { "7.620", "2.380", "3.860", "-18.160" };
        String[] bValues = new String[] { "7.62", "3.50", "1.90", "-1.45" };
        DecimalVector valuesa = decimalVector(aValues, aType.getPrecision(), aType.getScale());
        DecimalVector valuesb = decimalVector(bValues, bType.getPrecision(), bType.getScale());
        batch = new ArrowRecordBatch(numRows, Lists.newArrayList(new ArrowFieldNode(numRows, 0), new ArrowFieldNode(numRows, 0)), Lists.newArrayList(valuesa.getValidityBuffer(), valuesa.getDataBuffer(), valuesb.getValidityBuffer(), valuesb.getDataBuffer()));
        // expected results.
        boolean[][] expected = { // eq
        { true, false, false, false }, // ne
        { false, true, true, true }, // lt
        { false, true, false, true }, // le
        { true, true, false, true }, // gt
        { false, false, true, false }, // ge
        { true, false, true, false } };
        // Allocate output vectors.
        output = new ArrayList<>(Arrays.asList(new BitVector("eq", allocator), new BitVector("ne", allocator), new BitVector("lt", allocator), new BitVector("le", allocator), new BitVector("gt", allocator), new BitVector("ge", allocator)));
        for (ValueVector v : output) {
            v.allocateNew();
        }
        // evaluate expressions.
        eval.evaluate(batch, output);
        // compare the outputs.
        for (int idx = 0; idx < output.size(); ++idx) {
            boolean[] expectedArray = expected[idx];
            BitVector resultVector = (BitVector) output.get(idx);
            for (int i = 0; i < numRows; i++) {
                assertFalse(resultVector.isNull(i));
                assertEquals("mismatch in result for expr at idx " + idx + " for row " + i, expectedArray[i], resultVector.getObject(i).booleanValue());
            }
        }
    } finally {
        // free buffers
        if (batch != null) {
            releaseRecordBatch(batch);
        }
        if (output != null) {
            releaseValueVectors(output);
        }
        eval.close();
    }
}

