    Field dec = Field.nullable("dec", decimalType);
    Field str = Field.nullable("str", new ArrowType.Utf8());
    TreeNode field = TreeBuilder.makeField(str);
    List<TreeNode> args = Lists.newArrayList(field);
    TreeNode cast = TreeBuilder.makeFunction("castDECIMAL", args, decimalType);
    ExpressionTree tree = TreeBuilder.makeExpression(cast, Field.nullable("dec_str", decimalType));
    Schema schema = new Schema(Lists.newArrayList(str));
    Projector eval = Projector.make(schema, Lists.newArrayList(tree));
    List<ValueVector> output = null;
    ArrowRecordBatch batch = null;
    try {
        int numRows = 4;
        String[] aValues = new String[] { "10.5134", "-0.1", "10.516", "-1000" };
        VarCharVector valuesa = varcharVector(aValues);
        batch = new ArrowRecordBatch(numRows, Lists.newArrayList(new ArrowFieldNode(numRows, 0)), Lists.newArrayList(valuesa.getValidityBuffer(), valuesa.getOffsetBuffer(), valuesa.getDataBuffer()));
        DecimalVector resultVector = new DecimalVector("res", allocator, decimalType.getPrecision(), decimalType.getScale());
        resultVector.allocateNew();
        output = new ArrayList<>(Arrays.asList(resultVector));
        BigDecimal[] expected = { BigDecimal.valueOf(10.51), BigDecimal.valueOf(-0.10), BigDecimal.valueOf(10.52), BigDecimal.valueOf(0.00) };
        // evaluate expressions.
        eval.evaluate(batch, output);
        // compare the outputs.
        for (int i = 0; i < numRows; i++) {
            assertTrue("mismatch in result for " + "field " + resultVector.getField().getName() + " for row " + i + " expected " + expected[i] + ", got " + resultVector.getObject(i), expected[i].compareTo(resultVector.getObject(i)) == 0);
        }
    } finally {
        // free buffers
        if (batch != null) {
            releaseRecordBatch(batch);
        }
        if (output != null) {
            releaseValueVectors(output);
        }
        eval.close();
    }
}

