     */
    Field x = Field.nullable("x", new ArrowType.Int(32, true));
    ArrowType retType = new ArrowType.Utf8();
    TreeNode ifHiBye = TreeBuilder.makeIf(TreeBuilder.makeFunction("greater_than_or_equal_to", Lists.newArrayList(TreeBuilder.makeField(x), TreeBuilder.makeLiteral(0)), boolType), TreeBuilder.makeStringLiteral("hi"), TreeBuilder.makeStringLiteral("bye"), retType);
