    ArrowFieldNode fieldNode = new ArrowFieldNode(numRows, 0);
    ArrowRecordBatch batch = new ArrowRecordBatch(numRows, Lists.newArrayList(fieldNode, fieldNode), Lists.newArrayList(validityX, dataBufsX.get(0), dataBufsX.get(1)));
