@Test
public void testMemoryUsage() {
    ListAppender<ILoggingEvent> memoryLogsAppender = new ListAppender<>();
    Logger logger = (Logger) LoggerFactory.getLogger("arrow.allocator");
    try {
        logger.setLevel(Level.TRACE);
        logger.addAppender(memoryLogsAppender);
        memoryLogsAppender.start();
        try (ArrowBuf buf = new ArrowBuf(ReferenceManager.NO_OP, null, 1024, new PooledByteBufAllocatorL().empty.memoryAddress())) {
            buf.memoryAddress();
        }
        boolean result = false;
        long startTime = System.currentTimeMillis();
        while ((System.currentTimeMillis() - startTime) < 10000) {
            // 10 seconds maximum for time to read logs
            result = memoryLogsAppender.list.stream().anyMatch(log -> log.toString().contains("Memory Usage: \n") && log.toString().contains("Large buffers outstanding: ") && log.toString().contains("Normal buffers outstanding: ") && log.getLevel().equals(Level.TRACE));
            if (result) {
                break;
            }
        }
        assertTrue("Log messages are:\n" + memoryLogsAppender.list.stream().map(ILoggingEvent::toString).collect(Collectors.joining("\n")), result);
    } finally {
        memoryLogsAppender.stop();
        logger.detachAppender(memoryLogsAppender);
        logger.setLevel(null);
    }
}

