                    assertEquals(1, decodedVector.getValueCount());
                    assertArrayEquals("255".getBytes(), decodedVector.get(0));
                }
            }
        }
    }
}

@Test
public void testSecBasics() {
    try (DurationVector secVector = TestUtils.newVector(DurationVector.class, "second", new ArrowType.Duration(TimeUnit.SECOND), allocator)) {
