        assertEquals(expectedField, writer.getField());
    }
}

@Test
public void testWriterGetFixedSizeBinaryField() throws Exception {
    // Adapted from: TestComplexWriter.java:fixedSizeBinaryWriters
    // test values
    int numValues = 10;
    int byteWidth = 9;
    byte[][] values = new byte[numValues][byteWidth];
    for (int i = 0; i < numValues; i++) {
        for (int j = 0; j < byteWidth; j++) {
            values[i][j] = ((byte) i);
        }
    }
    ArrowBuf[] bufs = new ArrowBuf[numValues];
    for (int i = 0; i < numValues; i++) {
        bufs[i] = allocator.buffer(byteWidth);
        bufs[i].setBytes(0, values[i]);
    }
    try (final ListVector vector = ListVector.empty("list", allocator)) {
        org.apache.arrow.vector.complex.writer.FieldWriter writer = vector.getWriter();
        writer.allocate();
        FixedSizeBinaryHolder binHolder = new FixedSizeBinaryHolder();
        binHolder.byteWidth = byteWidth;
        writer.startList();
        for (int i = 0; i < numValues; i++) {
            binHolder.buffer = bufs[i];
            writer.fixedSizeBinary().write(binHolder);
        }
        // Writing with a different byteWidth should throw
        // Note just reusing the last buffer value since that won't matter here anyway
        binHolder.byteWidth = 3;
        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class, () -> writer.fixedSizeBinary().write(binHolder));
        assertEquals("holder.byteWidth: 3 not equal to vector byteWidth: 9", ex.getMessage());
        writer.endList();
        vector.setValueCount(1);
        Field expectedDataField = new Field(BaseRepeatedValueVector.DATA_VECTOR_NAME, FieldType.nullable(new ArrowType.FixedSizeBinary(byteWidth)), null);
        Field expectedField = new Field(vector.getName(), FieldType.nullable(ArrowType.List.INSTANCE), Arrays.asList(expectedDataField));
        assertEquals(expectedField, writer.getField());
    }
    AutoCloseables.close(bufs);
}

@Test
public void testClose() throws Exception {
    try (final ListVector vector = ListVector.empty("list", allocator)) {
        UnionListWriter writer = vector.getWriter();
        writer.allocate();
        //set some values
        writer.startList();
        writer.integer().writeInt(1);
        writer.integer().writeInt(2);
        writer.endList();
        vector.setValueCount(2);
        assertTrue(vector.getBufferSize() > 0);
        assertTrue(vector.getDataVector().getBufferSize() > 0);
        writer.close();
        assertEquals(0, vector.getBufferSize());
        assertEquals(0, vector.getDataVector().getBufferSize());
    }
}

@Test
public void testGetBufferSizeFor() {
    try (final ListVector vector = ListVector.empty("list", allocator)) {
        UnionListWriter writer = vector.getWriter();
        writer.allocate();
        //set some values
        writeIntValues(writer, new int[] { 1, 2 });
        writeIntValues(writer, new int[] { 3, 4 });
        writeIntValues(writer, new int[] { 5, 6 });
        writeIntValues(writer, new int[] { 7, 8, 9, 10 });
        writeIntValues(writer, new int[] { 11, 12, 13, 14 });
        writer.setValueCount(5);
        IntVector dataVector = (IntVector) vector.getDataVector();
        int[] indices = new int[] { 0, 2, 4, 6, 10, 14 };
        for (int valueCount = 1; valueCount <= 5; valueCount++) {
            int validityBufferSize = BitVectorHelper.getValidityBufferSize(valueCount);
            int offsetBufferSize = (valueCount + 1) * BaseRepeatedValueVector.OFFSET_WIDTH;
            int expectedSize = validityBufferSize + offsetBufferSize + dataVector.getBufferSizeFor(indices[valueCount]);
            assertEquals(expectedSize, vector.getBufferSizeFor(valueCount));
        }
    }
}

